(function(g){"use strict";function mean(a){return a.reduce((s,x)=>s+x,0)/a.length}function mae(a,b){return mean(a.map((v,i)=>Math.abs(v-b[i])))}function reg(x,y){let xm=mean(x),ym=mean(y);let b=x.reduce((s,v,i)=>s+(v-xm)*(y[i]-ym),0)/(x.reduce((s,v)=>s+(v-xm)**2,0)||1);return {a:ym-b*xm,b}}function median(a){a=a.slice().sort((x,y)=>x-y);return a[Math.floor(a.length/2)]}function rng(seed){return ()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296}}function run(p){let all=[];function calc(n,s){let q=p.demand/n,H=70*s*s-.0008*q*q,eta=Math.max(.38,.82-.000018*(q-125*s)**2-.12*(s-1)**2);let feasible=H>=p.head&&q>=55*s&&q<=230*s;let power=850*9.81*(p.demand/3600)*Math.max(0,H)/eta/1000;return{n,s,H,eta,power,feasible}}for(let n=1;n<=3;n++)for(let k=65;k<=115;k++)all.push(calc(n,k/100));let f=all.filter(x=>x.feasible).sort((a,b)=>a.power-b.power),b=[1,2,3].map(n=>calc(n,1)).filter(x=>x.feasible).sort((a,b)=>a.power-b.power),best=f[0],base=b[0];return {summary:best?'可行集中最低功率：'+best.n+' 台泵，转速 '+best.s.toFixed(2)+'，扬程 '+best.H.toFixed(1)+' m。':'本轮没有可行组合：需要核对输量、最低扬程与设备能力。',metrics:[['可行/全部候选',f.length+'/'+all.length],['最优功率',best?best.power.toFixed(1)+' kW':'无可行解'],['额定转速基线',base?base.power.toFixed(1)+' kW':'无可行解'],['日费用',best?(best.power*24*p.price).toFixed(0)+' 元':'—']],charts:[{title:'候选组合的扬程与电功率：逐点搜索',xlabel:'产生扬程 H，m',ylabel:'kW',scatter:true,series:[{name:'可行工况',x:all.filter(x=>x.feasible).map(x=>x.H),y:all.filter(x=>x.feasible).map(x=>x.power)},{name:'不满足约束',x:all.filter(x=>!x.feasible).map(x=>x.H),y:all.filter(x=>!x.feasible).map(x=>x.power)}],threshold:p.head}],headers:['路线','泵数','转速','扬程 m','总效率 %','电功率 kW','费用 元/日'],rows:f.slice(0,12).map((x,i)=>[i?'可行候选':'最优',x.n,x.s.toFixed(2),x.H.toFixed(1),(100*x.eta).toFixed(1),x.power.toFixed(1),(x.power*24*p.price).toFixed(0)]).concat(base?[['额定基线',base.n,'1.00',base.H.toFixed(1),(100*base.eta).toFixed(1),base.power.toFixed(1),(base.power*24*p.price).toFixed(0)]]:[]),denominator:all.length,best:best||null,base:base||null,candidates:all,referenceUsedOnlyInEvaluation:true}};g.TransportEngine={run:run};})(globalThis);

